import test from "node:test";
import assert from "node:assert/strict";
import { masterDashboardUrl, redirectToMaster } from "../web/redirect.js";

const localId = "98a316a679fc", masterId = "98a316a678ac";
const masterIp = "192.168.1.106";
const follower = () => ({
	master: false, settled: true, electionPending: false, localId, masterId, masterIp,
	devices: [{ id: masterId, ip: masterIp, online: true }],
});
const master = () => ({ master: true, settled: true, electionPending: false, localId: masterId, masterId });

test("a confirmed master replaces the follower URL without adding a history entry", async () => {
	const navigation = [];
	const location = { hostname: "192.168.1.112", replace: (url) => navigation.push(url) };
	assert.equal(await redirectToMaster(follower(), location, async (address, command, options) => {
		assert.equal(address, "http://" + masterIp);
		assert.deepEqual(command, { op: "status" });
		assert.ok(options.signal);
		return master();
	}), true);
	assert.deepEqual(navigation, ["http://" + masterIp + "/"]);
});

test("startup, elections, self addresses, offline peers and untrusted destinations cannot redirect", () => {
	for (const patch of [{ master: true }, { settled: false }, { electionPending: true }, { masterId: localId },
		{ devices: [] }, { devices: null }, { devices: [null] }, { devices: [{ id: masterId, ip: masterIp, online: false }] }]) {
		assert.equal(masterDashboardUrl({ ...follower(), ...patch }, "192.168.1.112"), "");
	}
	assert.equal(masterDashboardUrl(follower(), masterIp), "");
	for (const ip of ["0.0.0.0", "127.0.0.1", "224.0.0.1", "255.255.255.255", "999.1.1.1", "192.168.01.106",
		"https://example.com", "192.168.1.106@evil.example", "192.168.1.106/evil", "192.168.1.106:80"]) {
		const status = { ...follower(), masterIp: ip, devices: [{ id: masterId, ip, online: true }] };
		assert.equal(masterDashboardUrl(status, "192.168.1.112"), "", ip);
	}
	assert.equal(masterDashboardUrl({ ...follower(), masterIp: "192.168.1.110" }, "192.168.1.112"), "");
});

test("stale or contradictory destination elections leave the current dashboard open", async () => {
	const location = { hostname: "192.168.1.112", replace: () => assert.fail("Unexpected navigation") };
	for (const patch of [{ master: false }, { settled: false }, { electionPending: true }, { localId }, { masterId: localId }]) {
		assert.equal(await redirectToMaster(follower(), location, async () => ({ ...master(), ...patch })), false);
	}
	assert.equal(await redirectToMaster(follower(), location, async () => { throw new Error("Network unavailable"); }), false);
});

test("an unreachable destination probe is bounded and can be retried by polling", async (context) => {
	context.mock.timers.enable({ apis: ["setTimeout"] });
	const location = { hostname: "192.168.1.112", replace: () => assert.fail("Unexpected navigation") };
	const pending = redirectToMaster(follower(), location, async (_, __, { signal }) => new Promise((_, reject) => {
		signal.addEventListener("abort", () => reject(new DOMException("Aborted", "AbortError")), { once: true });
	}));
	context.mock.timers.tick(3000);
	assert.equal(await pending, false);
});

// Exercise startup orchestration as well as the helper: navigation precedes effects and device hydration.
test("the real dashboard startup redirects before loading the effect catalog", async () => {
	const original = { fetch: globalThis.fetch, document: globalThis.document, window: globalThis.window, location: globalThis.location };
	const calls = [], controls = new Map();
	let navigated;
	const navigation = new Promise((resolve) => { navigated = resolve; });
	globalThis.document = {
		hidden: false, readyState: "complete", addEventListener() {},
		getElementById(id) { if (!controls.has(id)) controls.set(id, {}); return controls.get(id); },
	};
	globalThis.window = { addEventListener() {} };
	globalThis.location = { origin: "http://192.168.1.112", hostname: "192.168.1.112", replace: navigated };
	globalThis.fetch = async (address, options = {}) => {
		calls.push(address);
		assert.notEqual(address, "/json/effects");
		if (address.endsWith("/request")) return new Response(JSON.stringify({ id: "a".repeat(32) }));
		if (address.includes("/rpc?")) {
			assert.deepEqual(JSON.parse(options.body), { op: "status" });
			return new Response(null, { status: 202 });
		}
		return new Response(JSON.stringify({ ok: true, ...(address.startsWith("http://" + masterIp) ? master() : follower()) }));
	};
	let timeout;
	try {
		await import("../web/app.js?redirect-startup-test");
		window.glassDeviceBridge.start({
			setEnabled: (enabled) => assert.equal(enabled, false),
			receivePixels() {},
			receiveDevices: () => assert.fail("Follower controls hydrated before redirect"),
			receiveEffects: () => assert.fail("Effect catalog loaded before redirect"),
		});
		assert.equal(await Promise.race([navigation, new Promise((_, reject) => {
			timeout = setTimeout(() => reject(new Error("No automatic navigation")), 3000);
		})]), "http://" + masterIp + "/");
		await new Promise((resolve) => setTimeout(resolve, 0));
		assert.equal(calls.length, 6);
	} finally {
		clearTimeout(timeout);
		Object.assign(globalThis, original);
	}
});
